const _roman = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X'];

/// 0 → I … 9 → X (upgrade levels).
String roman(int index) =>
    index < _roman.length ? _roman[index] : '${index + 1}';

